   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The incident caught the attention of foreign spies. After that, as I mentioned, the unfinished device was stolen. We caught one thief, but he didn't reveal the hiding spot.", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Then how'd you track it here? Some kind of locator?", msg_color="", msg_size=0, talker="Snow Fox", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "1501", 0, 0, -56, 191}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
