   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I work in asset security at Divinelight Heavy Tech's HQ in the capital. That day, my partner and I split up chasing the thieves. I followed one here, and he activated the device, trying to use simulated Mutants to subdue me. But the creatures he created ended up throwing *him* off the cliff into the industrial ruins below.", msg_color="", msg_size=0, talker="Ivan", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7149", 0, 0, -18, 221.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
