   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Some bastards leaked the news. After calling HQ for backup, I had to deal with paranormal enthusiasts snooping around, posting footage online.", msg_color="", msg_size=0, talker="Ivan", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7149", 0, 0, -18, 221.5},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I couldn't let them find out the truth, and I had to keep the simulation density from getting out of control. So I used the data I had to simulate creatures—partly to scare people off, partly for self-defense.", msg_color="", msg_size=0, talker="Ivan", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7149", 0, 0, -18, 221.5},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
